content:
{
  "labels": [
    {
      "i": 0,
      "speaker": "bot",
      "text": "Hello मुकेश सोनम सिंह जी आपको कौन सा product चाहिए?"
    },
    {
      "i": 1,
      "speaker": "caller",
      "text": "ये poultry farm के लिए"
    },
    {
      "i": 2,
      "speaker": "bot",
      "text": "आपको जो पर्दे poultry farm में आमतौर पर मुर्गियों के shed या जगह को ढकने के लिए इस्तेमाल होते हैं वही चाहिए ना?"
    },
    {
      "i": 3,
      "speaker": "caller",
      "text": "पूरे details"
    },
    {
      "i": 4,
      "speaker": "caller",
      "text": "हाँ जी हाँ जी।"
    },
    {
      "i": 5,
      "speaker": "bot",
      "text": "ठीक है मैं Tanya बोल रही हूं IndiaMART से।"
    },
    {
      "i": 6,
      "speaker": "bot",
      "text": "हमारे पास कई अच्छे sellers available हैं जिनसे मैं अभी आपको connect करवाऊंगी।"
    },
    {
      "i": 7,
      "speaker": "bot",
      "text": "बस कुछ details confirm कर दीजिए।"
    },
    {
      "i": 8,
      "speaker": "bot",
      "text": "आपको कितने piece चाहिए?"
    },
    {
      "i": 9,
      "speaker": "caller",
      "text": "मुझे चाहिए सौ foot लम्बा है और चालीस foot चौड़ा है।"
    },
    {
      "i": 10,
      "speaker": "caller",
      "text": "side भी है तो की सात set"
    },
    {
      "i": 11,
      "speaker": "bot",
      "text": "पूरा details"
    },
    {
      "i": 12,
      "speaker": "bot",
      "text": "शुक्रिया।"
    },
    {
      "i": 13,
      "speaker": "bot",
      "text": "आपने height 7 feet बताई है।"
    },
    {
      "i": 14,
      "speaker": "bot",
      "text": "अब पर्दे की लंबाई के लिए आपके लिए 100 feet सही रहेगा?"
    },
    {
      "i": 15,
      "speaker": "bot",
      "text": "जैसे 100 feet, 150 feet या कुछ और?"
    },
    {
      "i": 16,
      "speaker": "caller",
      "text": "सौ feet एक side दूसरी side सौ feet।"
    },
    {
      "i": 17,
      "speaker": "caller",
      "text": "आमने सामने चालीस piece चालीस वाले"
    },
    {
      "i": 18,
      "speaker": "bot",
      "text": "बहुत बढ़िया तो आपने दोनों sides और सामने की लंबाई clear बता दी है।"
    },
    {
      "i": 19,
      "speaker": "bot",
      "text": "अब पर्दे का material weight कितना चाहिए जैसे 200 gram प्रति वर्ग meter, 250 gram प्रति वर्ग meter या कुछ और?"
    },
    {
      "i": 20,
      "speaker": "caller",
      "text": "मुझे चाहिए डेढ़ सौ kg में"
    },
    {
      "i": 21,
      "speaker": "caller",
      "text": "और दो सौ के आसपास।"
    },
    {
      "i": 22,
      "speaker": "bot",
      "text": "ठीक है।"
    },
    {
      "i": 23,
      "speaker": "bot",
      "text": "आपने एक सौ पचास gram प्रति वर्ग meter और लगभग दो सौ gram प्रति वर्ग meter दोनों बताए हैं।"
    },
    {
      "i": 24,
      "speaker": "bot",
      "text": "ये detail seller को भेज दी जाएंगी।"
    },
    {
      "i": 25,
      "speaker": "bot",
      "text": "अब अपनी city और state भी बता।"
    },
    {
      "i": 26,
      "speaker": "caller",
      "text": "नहीं।"
    },
    {
      "i": 27,
      "speaker": "caller",
      "text": "वर्ग meter नहीं GSM होना चाहिए उसका weight."
    },
    {
      "i": 28,
      "speaker": "bot",
      "text": "बिल्कुल आपने सही कहा GSM यानी ग्राम प्रति वर्ग meter में ही weight होता है।"
    },
    {
      "i": 29,
      "speaker": "bot",
      "text": "आपकी details इसी हिसाब से भेजी जाएंगी।"
    }
  ]
}
